53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        // Normalize the address up front so every downstream use (the required-field check,
115	        // household-duplicate detection, the shared household id and the stored/returned value)
116	        // works from the same canonical form.
117	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
118	        List<String> missingFields = new ArrayList<>();
119	        if (isBlank(ownerFieldsDto.getFirstName())) {
120	            missingFields.add("firstName");
121	        }
122	        if (isBlank(ownerFieldsDto.getLastName())) {
123	            missingFields.add("lastName");
124	        }
125	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
126	        if (isBlank(normalizedAddress)) {
127	            missingFields.add("address");
128	        }
129	        if (isBlank(ownerFieldsDto.getCity())) {
130	            missingFields.add("city");
131	        }
132	        if (isBlank(ownerFieldsDto.getTelephone())) {
133	            missingFields.add("telephone");
134	        }
135	        if (!missingFields.isEmpty()) {
136	            throw new InvalidOwnerFieldsException(missingFields);
137	        }
138	        // Determine the effective registration date up front so every downstream use (the daily
139	        // create-limit, the stored value and anything derived from it such as the membership number's
140	        // year segment) works from the same business-day-adjusted date. The effective date is the
141	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
142	        // forward to the following Monday.
143	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
144	            ? ownerFieldsDto.getRegistrationDate()
145	            : LocalDate.now();
146	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
147	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
148	        // already carry this adjusted business day's registration date, no further owners may be
149	        // created for that day.
150	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= MAX_OWNERS_PER_DAY) {
151	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
152	        }
153	        // Reject the request when the owner's city is already full: a city that already holds the
154	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
155	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
156	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
157	        }
158	        // Normalize the telephone into E.164 form; a number that cannot form a valid
159	        // E.164 value is rejected with a 400.
160	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
161	        // Email is optional; when present it must be a syntactically valid address and is
162	        // stored lower-cased. An invalid address is rejected with a 400.
163	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
164	        // Reject the request if the E.164 telephone is already used by any other owner.
165	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
166	            .map(Owner::getTelephone)
167	            .filter(existing -> existing != null)
168	            .anyMatch(normalizedTelephone::equals);
169	        if (telephoneInUse) {
170	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
171	        }
172	        // Household handling for a matching last name + address (compared case-insensitively with
173	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
174	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
175	        // household and every member (the new owner and any existing ones) is stamped with the same
176	        // stable 'householdId'.
177	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
178	        String householdId = null;
179	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
180	            householdId = householdId(normalizedLastName, normalizedAddress);
181	            // Backfill the shared identifier onto any existing member of this household so the whole
182	            // household carries the same stable value.
183	            for (Owner existing : this.clinicService.findAllOwners()) {
184	                if (collapse(existing.getLastName()).equals(normalizedLastName)
185	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
186	                    && !householdId.equals(existing.getHouseholdId())) {
187	                    existing.setHouseholdId(householdId);
188	                    this.clinicService.saveOwner(existing);
189	                }
190	            }
191	        } else {
192	            boolean householdInUse = this.clinicService.findAllOwners().stream()
193	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
194	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
195	            if (householdInUse) {
196	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
197	            }
198	        }
199	        HttpHeaders headers = new HttpHeaders();
200	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
201	        owner.setAddress(normalizedAddress);
202	        owner.setTelephone(normalizedTelephone);
203	        owner.setEmail(normalizedEmail);
204	        owner.setHouseholdId(householdId);
205	        // Record how many existing owners (before this create) share this owner's first and last
206	        // name, compared case-insensitively. Computed against the current owners so the new owner
207	        // itself is never counted.
208	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
209	        // Store the business-day-adjusted effective registration date computed above. This defaults
210	        // to the server's current date when none was supplied and rolls any weekend date forward to
211	        // the following Monday, so everything derived from it (e.g. the membership number's year
212	        // segment) uses the adjusted date.
213	        owner.setRegistrationDate(effectiveRegistrationDate);
214	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
215	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
216	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
217	        // owners already in that city.
218	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
219	        this.clinicService.saveOwner(owner);
220	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
221	        headers.setLocation(UriComponentsBuilder.newInstance()
222	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
223	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
229	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
230	        if (currentOwner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        currentOwner.setAddress(ownerFieldsDto.getAddress());
234	        currentOwner.setCity(ownerFieldsDto.getCity());
235	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
236	        currentOwner.setLastName(ownerFieldsDto.getLastName());
237	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
238	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
239	        this.clinicService.saveOwner(currentOwner);
240	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Transactional
245	    @Override
246	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner == null) {
249	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	        }
251	        this.clinicService.deleteOwner(owner);
252	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner == null) {
260	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	        }
262	        HttpHeaders headers = new HttpHeaders();
263	        Pet pet = petMapper.toPet(petFieldsDto);
264	        owner.setId(ownerId);
265	        pet.setOwner(owner);
266	        pet.getType().setName(null);
267	        this.clinicService.savePet(pet);
268	        PetDto petDto = petMapper.toPetDto(pet);
269	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
270	            .buildAndExpand(pet.getId()).toUri());
271	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
277	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
278	        if (currentOwner != null) {
279	            Pet currentPet = this.clinicService.findPetById(petId);
280	            if (currentPet != null) {
281	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
282	                currentPet.setName(petFieldsDto.getName());
283	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
284	                this.clinicService.savePet(currentPet);
285	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
286	            }
287	        }
288	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	    }
290	
291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
294	        HttpHeaders headers = new HttpHeaders();
295	        Visit visit = visitMapper.toVisit(visitFieldsDto);
296	        Pet pet = new Pet();
297	        pet.setId(petId);
298	        visit.setPet(pet);
299	        this.clinicService.saveVisit(visit);
300	        VisitDto visitDto = visitMapper.toVisitDto(visit);
301	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
302	            .buildAndExpand(visit.getId()).toUri());
303	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
304	    }
305	
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Override
309	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
310	        Owner owner = this.clinicService.findOwnerById(ownerId);
311	        if (owner != null) {
312	            Pet pet = owner.getPet(petId);
313	            if (pet != null) {
314	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
315	            }
316	        }
317	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
318	    }
319	
320	    private static boolean isBlank(String value) {
321	        return value == null || value.trim().isEmpty();
322	    }
323	
324	    /**
325	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
326	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
327	     * compared case-insensitively with collapsed whitespace.
328	     */
329	    private static String collapse(String value) {
330	        if (value == null) {
331	            return "";
332	        }
333	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
334	    }
335	
336	    /**
337	     * Common street-type abbreviations expanded during address normalization.
338	     */
339	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
340	        "ST", "STREET",
341	        "RD", "ROAD",
342	        "AVE", "AVENUE");
343	
344	    /**
345	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
346	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
347	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
348	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
349	     * address maps to itself.
350	     */
351	    private static String normalizeAddress(String value) {
352	        if (value == null) {
353	            return "";
354	        }
355	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
356	        if (collapsed.isEmpty()) {
357	            return "";
358	        }
359	        String[] tokens = collapsed.split(" ");
360	        StringBuilder sb = new StringBuilder(collapsed.length());
361	        for (int i = 0; i < tokens.length; i++) {
362	            if (i > 0) {
363	                sb.append(' ');
364	            }
365	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
366	        }
367	        return sb.toString();
368	    }
369	
370	    /**
371	     * Derive the stable household identifier shared by owners with the same normalized last name
372	     * and address. It is a deterministic function of those two values, so every member of a
373	     * household independently derives the same identifier: the first 12 upper-case hex characters
374	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
375	     */
376	    private static String householdId(String normalizedLastName, String normalizedAddress) {
377	        try {
378	            byte[] digest = MessageDigest.getInstance("SHA-256")
379	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
380	            StringBuilder sb = new StringBuilder(digest.length * 2);
381	            for (byte b : digest) {
382	                sb.append(String.format("%02x", b));
383	            }
384	            return sb.substring(0, 12).toUpperCase();
385	        }
386	        catch (NoSuchAlgorithmException e) {
387	            throw new IllegalStateException("SHA-256 not available", e);
388	        }
389	    }
390	
391	    /**
392	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
393	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
394	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
395	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
396	     */
397	    /**
398	     * Count the existing owners that share the given first and last name, compared
399	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
400	     * namesakes that already existed at creation time (the new owner itself is not included).
401	     */
402	    private int countNamesakes(String firstName, String lastName) {
403	        return (int) this.clinicService.findAllOwners().stream()
404	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
405	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
406	                && existing.getLastName().equalsIgnoreCase(lastName))
407	            .count();
408	    }
409	
410	    /**
411	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
412	     * request to create another owner in it is rejected as a conflict.
413	     */
414	    private static final int MAX_OWNERS_PER_CITY = 50;
415	
416	    /**
417	     * Count the existing owners registered in the given city, compared case-insensitively (as in
418	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
419	     * reflects the owners that already existed at creation time.
420	     */
421	    private int countOwnersInCity(String city) {
422	        return (int) this.clinicService.findAllOwners().stream()
423	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
424	            .count();
425	    }
426	
427	    /**
428	     * The maximum number of owners that may be created on a single day. Once this many owners
429	     * already carry a given day's registration date, a request to create another owner that day is
430	     * rejected with a 429.
431	     */
432	    private static final int MAX_OWNERS_PER_DAY = 100;
433	
434	    /**
435	     * Count the existing owners whose registration date is the given day. Called before the new
436	     * owner is saved, so the returned value reflects the owners that already existed at creation
437	     * time.
438	     */
439	    private int countOwnersRegisteredOn(LocalDate date) {
440	        return (int) this.clinicService.findAllOwners().stream()
441	            .filter(existing -> date.equals(existing.getRegistrationDate()))
442	            .count();
443	    }
444	
445	    /**
446	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
447	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
448	     * supplied or defaulted) always falls on a business day.
449	     */
450	    private static LocalDate toBusinessDay(LocalDate date) {
451	        return switch (date.getDayOfWeek()) {
452	            case SATURDAY -> date.plusDays(2);
453	            case SUNDAY -> date.plusDays(1);
454	            default -> date;
455	        };
456	    }
457	
458	    private String nextCustomerCode(String city, String lastName) {
459	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
460	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
461	        long sequence = this.clinicService.findAllOwners().stream()
462	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
463	            .count() + 1L;
464	        return String.format("%s-%s-%04d", city3, last3, sequence);
465	    }
466	
467	    /**
468	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
469	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
470	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
471	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
472	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
473	     */
474	    private static String toE164(String raw) {
475	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
476	        boolean hasCountryCode = cleaned.startsWith("+");
477	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
478	        if (!digits.matches("\\d+")) {
479	            throw new InvalidOwnerFieldsException(List.of("telephone"));
480	        }
481	        if (!hasCountryCode) {
482	            if (digits.startsWith("0")) {
483	                digits = digits.substring(1);
484	            }
485	            digits = "61" + digits;
486	        }
487	        if (digits.length() < 8 || digits.length() > 15) {
488	            throw new InvalidOwnerFieldsException(List.of("telephone"));
489	        }
490	        return "+" + digits;
491	    }
492	
493	    /**
494	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
495	     * and a domain with at least one dot-separated label, none of which contain whitespace or
496	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
497	     */
498	    private static final Pattern EMAIL_PATTERN =
499	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
500	
501	    /**
502	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
503	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
504	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
505	     * 400. A valid address is returned lower-cased.
506	     */
507	    private static String normalizeEmail(String email) {
508	        if (email == null || email.isEmpty()) {
509	            return null;
510	        }
511	        String trimmed = email.trim();
512	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
513	            throw new InvalidOwnerFieldsException(List.of("email"));
514	        }
515	        return trimmed.toLowerCase();
516	    }
517	}
